<script setup lang="ts">import {ref,computed} from 'vue';import PageHeading from '../components/common/PageHeading.vue';import Notice from '../components/common/Notice.vue';import Status from '../components/common/Status.vue';import {useTask} from '../hooks/useTask';import {researchApi} from '../api/research';import {download} from '../api/client';import {fmt} from '../utils/format';
const p=defineProps<{runs:any[];memos:any[];user:any;reloadResearch:()=>Promise<void>}>();
const success=computed(()=>p.runs.filter(r=>r.status==='completed')),id=ref(0),name=ref('分类边界复核 '+new Date().toLocaleTimeString()),interpretation=ref('κ是相对类别基率的一致性，不是与金标准对照的准确率。'),next=ref('保持原三位标记者，独立复核争议试样，明确图谱类别边界。'),task=useTask();
const run=computed(()=>success.value.find(r=>r.id===(id.value||success.value[0]?.id)));
const missing=computed(()=>run.value?.batch?.missing_snapshot===true),drifted=computed(()=>run.value?.batch?.has_snapshot&&run.value.batch.current_matches_queued===false);
const runTag=(r:any)=>r.batch?.missing_snapshot?'（缺原始资料·不可建说明）':r.batch?.current_matches_queued===false?'（排队后已改票·按原批）':'';
async function create(){await task.act(async()=>{await researchApi.createMemo({run_id:run.value.id,name:name.value,interpretation:interpretation.value,next_step:next.value});await p.reloadResearch()},'口径复核说明已提交')}
async function approve(m:any,status:string){await task.act(async()=>{await researchApi.approve(m.id,{status,review_note:status==='approved'?'批准固定面板口径复核；一致性不代表准确率。':'请补充试样独立性与类别边界说明。'});await p.reloadResearch()},status==='approved'?'说明已批准':'说明已退回')}
const short=(v?:string|null)=>v?v.slice(0,12)+'…'+v.slice(-8):'—';
</script><template><PageHeading index="05" title="把争议留给复核，把快照留在簿里。" description="人工解释和独立复核行动由负责人审阅；说明冻结整份统计、bootstrap与排队资料批次，后续改票不改写。"/><form v-if="user.role!=='viewer'" class="input-sheet memo-form" @submit.prevent="create"><div class="field-pair"><label>完成运行<select :value="run?.id||0" @change="id=Number(($event.target as HTMLSelectElement).value)"><option v-for="r in success" :key="r.id" :value="r.id" :disabled="r.batch?.missing_snapshot">#{{r.id}} {{r.name}} {{runTag(r)}}</option></select></label><label>说明名称<input v-model="name" required/></label></div><div class="field-pair"><label>人工解释<textarea v-model="interpretation" rows="3" required/></label><label>独立复核行动<textarea v-model="next" rows="3" required/></label></div><Notice v-if="missing" error="该运行缺少排队时刻原始资料，不能建立复核说明；请对当前资料重新排队生成新运行。"/><Notice v-else-if="drifted" message="该运行排队后发生过改票/补注；说明将引用排队原批结果，不会混用当前资料。"/><button class="primary" :disabled="task.state.busy||!run||missing" type="submit">提交口径复核说明 →</button><Notice v-bind="task.state"/></form><article class="memo-record" v-for="m in memos" :key="m.id"><div class="section-head"><h2>{{m.name}}</h2><Status :value="m.status"/></div><p>{{m.interpretation}}</p><p><strong>下一步 / </strong>{{m.next_step}}</p><div class="snapshot-line">冻结研究 {{m.result_snapshot.source_study.name}} / {{m.result_snapshot.specimen_count}}试样 / κ{{fmt(m.result_snapshot.kappa,6)}} / 有效{{m.result_snapshot.bootstrap.valid_repeats}}次</div><div class="snapshot-line batch-line" v-if="m.result_snapshot.batch">资料批次 {{m.result_snapshot.batch.snapshot_version}}｜排队指纹 <span class="fingerprint">{{short(m.result_snapshot.batch.queued_fingerprint)}}</span>｜建说明时 {{m.result_snapshot.batch.current_matches_queued_at_memo?'与当前资料一致':'与当前资料不一致（已留痕，仍按原批）'}}</div><div class="snapshot-line batch-line" v-else>旧版说明：无排队批次信息，资料批次不可核对。</div><p v-if="m.review_note">审核 / {{m.review_note}}</p><div class="memo-actions"><template v-if="user.role==='admin'&&m.status==='draft'"><button @click="approve(m,'approved')">批准口径复核 ✓</button><button @click="approve(m,'rejected')">退回补充</button></template><button v-if="m.status==='approved'" @click="task.act(()=>download('/memos/'+m.id+'/export','rater-review-'+m.id+'.csv'),'已导出批准快照CSV')">导出批准快照 CSV ↗</button></div></article></template>
